rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    function isAuth() {
      return request.auth != null;
    }
    function uid() {
      return request.auth.uid;
    }
    function adminDoc() {
      return get(/databases/$(database)/documents/admins/$(request.auth.uid)).data;
    }
    function isActiveAdmin() {
      return isRealUser()
        && exists(/databases/$(database)/documents/admins/$(request.auth.uid))
        && adminDoc().isActive == true
        && adminDoc().role in ['super', 'sub']
        && (adminDoc().role == 'super' || adminDoc().permissions is list);
    }
    // Les anciens appels génériques restent réservés au super-admin.
    // Un sous-admin doit toujours passer par hasAdminPermission().
    function isAdmin() {
      return isActiveAdmin() && adminDoc().role == 'super';
    }
    function hasAdminPermission(permission) {
      return isActiveAdmin()
        && (adminDoc().role == 'super' || permission in adminDoc().permissions);
    }
    function isOwner(userId) {
      return isAuth() && uid() == userId;
    }
    function isSuperAdmin() {
      return isAdmin();
    }
    function isRealUser() {
      return isAuth() && request.auth.token.firebase.sign_in_provider != 'anonymous';
    }
    // Master Prompt "Corrections finales avant publication" — Bug Critique #1 :
    // l'accès par crochet ([field]) lève une erreur d'évaluation (donc refuse
    // silencieusement l'écriture) si le champ est absent d'un des deux côtés,
    // même quand le champ modifié n'a rien à voir avec celui-ci. .get(field, null)
    // ne lève jamais d'erreur — un champ absent des deux côtés reste "unchanged"
    // (null == null), un champ présent d'un seul côté est correctement détecté
    // comme changé. Comportement strictement identique quand le champ existe
    // déjà des deux côtés (cas normal) — élargissement de sécurité, pas un
    // relâchement : aucune écriture auparavant refusée à raison n'est permise
    // par ce changement.
    function unchanged(field) {
      return request.resource.data.get(field, null) == resource.data.get(field, null);
    }
    function vehicleUsersBlocked(firstUid, secondUid) {
      return exists(/databases/$(database)/documents/vehicle_user_blocks/$(firstUid)/blocked/$(secondUid))
        || exists(/databases/$(database)/documents/vehicle_user_blocks/$(secondUid)/blocked/$(firstUid));
    }
    function notPresent(field) {
      return !(field in request.resource.data);
    }
    // LOT 6 SECURITY (2026-09) — un `orderId` doit désormais être fourni et
    // correspondre exactement à la commande en cours de création. Avant ce
    // verrou, la fonction ne vérifiait que l'égalité arithmétique
    // "solde après == solde avant - montant" sur le document clients/{uid} —
    // une égalité qui ne référence AUCUN identifiant de commande. Dans une
    // transaction Firestore lancée par le client (livraison_screen.dart,
    // courses_screen.dart, create_order.dart, restaurant_menu.dart,
    // boulangerie_order_page.dart, colis_page.dart, eau_boissons_page.dart,
    // blanchisserie_page.dart — les 8 écrans qui créent une commande wallet
    // en débitant le client dans la même transaction), rien n'empêchait un
    // client malveillant (requête Firestore directe, pas l'app légitime) de
    // débiter son wallet UNE seule fois d'un montant X puis de créer
    // PLUSIEURS documents `orders` dans cette même transaction, chacun avec
    // `budget` (ou `totalAmount` boulangerie) == X : chaque commande évaluait
    // indépendamment la même égalité vraie une seule fois, donc toutes
    // passaient `isPaid:true` pour un unique débit — un seul paiement
    // validant N commandes. Le champ `lastPaidOrderId`, écrit par l'appelant
    // dans la même transaction que le débit, ne peut porter qu'UNE seule
    // valeur finale : seule la commande dont l'ID correspond exactement peut
    // désormais satisfaire ce contrôle, fermant la réutilisation d'un même
    // débit pour plusieurs commandes. Élargissement de sécurité pur — aucune
    // commande légitime (un débit, une commande, même transaction) n'est
    // affectée.
    function walletDebitMatchesPaidOrder(orderId) {
      let client = /databases/$(database)/documents/clients/$(uid());
      let amount = request.resource.data.get('sellerType', '') == 'boulangerie'
        ? request.resource.data.get('totalAmount', -1)
        : request.resource.data.budget + request.resource.data.get('shoppingBudget', 0);
      return exists(client)
        && get(client).data.wallet is int
        && getAfter(client).data.wallet is int
        && request.resource.data.get('shoppingBudget', 0) is int
        && amount is int
        && getAfter(client).data.wallet == get(client).data.wallet
          - amount
        && getAfter(client).data.get('lastPaidOrderId', '') == orderId;
    }

    // LOT 6.1 (walletDebitMatchesPaidReservation) → LOT 6.3 (superseded) —
    // historique conservé pour traçabilité de l'audit. LOT 6.1 avait d'abord
    // fermé la réutilisation de débit sur `event_reservations` avec un
    // mécanisme miroir de walletDebitMatchesPaidOrder (un champ
    // `lastPaidReservationId` corrélé à l'ID de la réservation). LOT 6.2 a
    // ensuite trouvé et fermé un second trou dans la MÊME approche
    // (`totalAmount:0` passait le contrôle sans jamais rien débiter).
    // LOT 6.3 a trouvé un troisième problème structurel, cette fois
    // insoluble en règles Firestore seules : rien ne validait `totalAmount`/
    // `items[].unitPrice` contre les vrais prix `event_offers` — un client
    // pouvait réserver des prestations réelles en déclarant un prix inventé,
    // plus bas. Revalider ça en règles exigerait de boucler sur `items[]`
    // (jusqu'à 50 éléments) et relire un document par élément — confirmé
    // dépasser la limite Firestore Rules "maximum of 1000 expressions to
    // evaluate" lors de cet audit. Remplacé entièrement par
    // `createEventReservationCF` (functions/eventReservations.js, Admin SDK,
    // recalcule totalAmount depuis les vrais event_offers) — voir la règle
    // `event_reservations.allow create: if false;` ci-dessous, qui rend
    // cette fonction inutile et l'a fait supprimer plutôt que la laisser
    // comme code mort.

    // Vérifie que la session courante correspond à la pharmacie propriétaire de la commande.
    // currentUid est lié par pharmacieLogin après validation du mot de passe.
    function isPharmacieOwnerOfOrder() {
      return isAuth()
        && 'pharmacieId' in resource.data
        && exists(/databases/$(database)/documents/pharmacies/$(resource.data.pharmacieId))
        && get(/databases/$(database)/documents/pharmacies/$(resource.data.pharmacieId)).data.currentUid == uid();
    }

    match /admins/{adminId} {
      allow read:  if isOwner(adminId) || isAdmin();
      // Super admin peut tout modifier (permissions, rôle, isActive…)
      // Tout admin peut mettre à jour uniquement ses propres champs OTP (2FA
      // login) et sa propre photo de profil (Master Prompt "photos manquantes").
      allow write: if isSuperAdmin()
        || (isOwner(adminId) && isActiveAdmin()
          && request.resource.data.diff(resource.data).affectedKeys()
              .hasOnly(['otpHash', 'otpCode', 'otpExpiry', 'otpAttempts', 'fcmToken', 'photoUrl']));
    }

    match /clients/{clientId} {
      allow read:   if isOwner(clientId) || isAdmin();
      // Le profil client est créé directement après Firebase Auth. Le wallet
      // doit impérativement démarrer à zéro : une création sans ce contrôle
      // permettrait à un client de s'attribuer un solde arbitraire avant que
      // les protections d'update ne s'appliquent.
      allow create: if isOwner(clientId)
        && request.resource.data.keys().hasOnly([
          'name', 'phone', 'email', 'wallet', 'cashOnDeliveryEnabled',
          'fakeOrderCount', 'createdAt'
        ])
        && request.resource.data.wallet is int
        && request.resource.data.wallet == 0
        && request.resource.data.cashOnDeliveryEnabled is bool
        && request.resource.data.cashOnDeliveryEnabled == true
        && request.resource.data.fakeOrderCount is int
        && request.resource.data.fakeOrderCount == 0;
      allow update: if isAdmin() ||
        (isOwner(clientId) && unchanged('wallet') && unchanged('fakeOrderCount') && unchanged('cashOnDeliveryEnabled')) ||
        // Débit wallet autorisé (paiement Ekbine côté client) — solde ne peut que diminuer
        (isOwner(clientId)
          && request.resource.data.wallet is int
          && request.resource.data.wallet >= 0
          && request.resource.data.wallet < resource.data.wallet
          && unchanged('fakeOrderCount') && unchanged('cashOnDeliveryEnabled'));
      allow delete: if isAdmin();
      match /wallet_transactions/{txId} {
        allow read:   if isOwner(clientId) || isAdmin();
        allow create: if isAdmin()
          || (isOwner(clientId)
            && request.resource.data.keys().hasOnly(['type','amount','description','orderId','createdAt','provider','txId'])
            && request.resource.data.amount is int);
        allow update: if false;
        allow delete: if isAdmin();
      }
      // Historique local des notifications push reçues sur le device — écrit
      // par NotificationService._saveNotification() (lib/services/
      // notification_service.dart) à chaque réception FCM, jamais par une
      // Cloud Function. Bug critique confirmé le 2026-07-20 (audit module
      // Notifications) : cette sous-collection n'avait jamais eu de règle
      // dédiée — tout écrivait/lisait en permission-denied depuis le début,
      // avalé silencieusement par les `catch (_) {}` déjà en place côté
      // Dart. Le centre de notifications (notification_center.dart) n'a
      // donc jamais fonctionné pour aucun client, sur aucun device.
      match /notifications/{notifId} {
        allow read:   if isOwner(clientId) || isAdmin();
        allow create: if isOwner(clientId);
        allow update: if isOwner(clientId)
          && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['isRead']);
        allow delete: if isOwner(clientId) || isAdmin();
      }
    }

    match /livreurs/{livreurId} {
      // Lecture par tous les authentifiés (anonymes inclus pour la carte client)
      allow read:   if isAuth();
      allow create: if isAdmin();
      // Le livreur peut mettre à jour son propre doc :
      // - sans toucher au wallet (GPS, isOnline, token…)
      // - OU en diminuant son wallet (déduction commission à l'acceptation)
      // LOT 6 SECURITY (2026-09) : `isSuspended` n'était protégé par AUCUNE
      // des deux branches ci-dessous — seul `wallet` l'était. Un livreur
      // suspendu pouvait donc s'auto-réactiver (`isSuspended: false`) par une
      // simple écriture directe sur son propre document, contournant
      // entièrement la suspension admin. Confirmé exploitable : aucune des
      // deux branches ne limite les AUTRES champs modifiables (pas de
      // `hasOnly()`), donc `isSuspended` passait déjà comme n'importe quel
      // autre champ non listé. Corrigé en ajoutant `unchanged('isSuspended')`
      // aux deux branches — champ désormais réservé à isAdmin(), comme prévu
      // dès l'origine (cohérent avec le même verrou déjà en place sur
      // `ekbine_agents.isSuspended`). GPS/isOnline/fcmToken/token et tout
      // autre champ opérationnel restent inchangés et toujours modifiables
      // par le livreur — aucun appelant Dart légitime n'écrit `isSuspended`
      // depuis le livreur lui-même (seul `drivers_page.dart`, admin-only,
      // l'écrit).
      allow update: if isAdmin()
        || (isOwner(livreurId) && unchanged('wallet') && unchanged('isSuspended'))
        || (isOwner(livreurId)
            && request.resource.data.wallet is int
            && request.resource.data.wallet >= 0
            && request.resource.data.wallet < resource.data.wallet
            && unchanged('isSuspended'));
      allow delete: if isAdmin();
      match /wallet_transactions/{txId} {
        allow read:   if isOwner(livreurId) || isAdmin();
        allow create: if isAdmin()
          || (isOwner(livreurId)
            && request.resource.data.keys().hasOnly(['type','amount','description','orderId','createdAt','provider','txId'])
            && request.resource.data.amount is int);
        allow update: if false;
        allow delete: if isAdmin();
      }
    }

    match /driver_requests/{requestId} {
      allow create: if isRealUser() && request.resource.data.uid == uid();
      allow read:   if isAdmin() || (isAuth() && resource.data.uid == uid());
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    match /sellers/{sellerId} {
      allow read:   if isOwner(sellerId) || hasAdminPermission('demandes_vendeurs');
      allow create: if hasAdminPermission('demandes_vendeurs');
      allow update: if hasAdminPermission('demandes_vendeurs') || (isOwner(sellerId)
        && unchanged('wallet')
        && unchanged('subscriptionStatus') && unchanged('subscriptionExpiresAt')
        && unchanged('vipStatus') && unchanged('vipExpiresAt')
        && unchanged('vipStartedAt') && unchanged('plan')
        && unchanged('priorityLevel') && unchanged('paymentStatus'));
      allow delete: if isAdmin();
      match /wallet_transactions/{txId} {
        allow read:   if isOwner(sellerId) || isAdmin();
        allow create: if isAdmin()
          || (isOwner(sellerId)
            && request.resource.data.keys().hasOnly(['type','amount','description','orderId','createdAt'])
            && request.resource.data.amount is int);
        allow update: if false;
        allow delete: if isAdmin();
      }
    }

    match /seller_requests/{requestId} {
      allow create: if isRealUser() && request.resource.data.uid == uid();
      allow read:   if isAdmin() || (isAuth() && resource.data.uid == uid());
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    match /restaurants/{restaurantId} {
      allow read:  if isAuth();
      allow write: if isAdmin();

      // Master Prompt "photos manquantes" : le propriétaire (restaurant_owners
      // ownerId -> restaurantId, même lookup que la sous-collection menu
      // ci-dessous) peut modifier son logo et son statut ouvert/fermé — jamais
      // le wallet ni aucun autre champ. `isOpen` était déjà écrit directement
      // par le client (restaurant_owner_dashboard.dart:_toggleOpen) sans
      // qu'aucune règle owner ne l'autorise jusqu'ici — corrigé au passage,
      // même portée de risque que l'ajout de logoUrl.
      allow update: if isRealUser()
        && get(/databases/$(database)/documents/restaurant_owners/$(request.auth.uid))
            .data.get('restaurantId', '') == restaurantId
        && request.resource.data.diff(resource.data).affectedKeys()
            .hasOnly(['logoUrl', 'coverImageUrl', 'isOpen']);
      // Le propriétaire Firebase Auth ne peut écrire que le token du
      // restaurant auquel restaurant_owners/{uid} le rattache.
      allow update: if isRealUser()
        && get(/databases/$(database)/documents/restaurant_owners/$(request.auth.uid))
            .data.get('restaurantId', '') == restaurantId
        && request.resource.data.diff(resource.data).affectedKeys()
            .hasOnly(['fcmToken'])
        && request.resource.data.fcmToken is string
        && request.resource.data.fcmToken.size() > 10
        && request.resource.data.fcmToken.size() <= 4096;

      // Sous-collection utilisée par restaurant_owner_dashboard.dart
      match /menu/{menuId} {
        allow read: if isAuth();
        allow write: if isAdmin()
          || (isRealUser()
            && get(/databases/$(database)/documents/restaurant_owners/$(request.auth.uid))
                .data.get('restaurantId', '') == restaurantId);
      }

      // Ancienne sous-collection (conservée pour compatibilité)
      match /menus/{menuId} {
        allow read:  if isAuth();
        allow write: if isAdmin();
      }
    }

    match /restaurant_owners/{ownerId} {
      allow read:  if isOwner(ownerId) || isAdmin();
      allow write: if isAdmin();
    }

    match /restaurant_requests/{requestId} {
      allow create: if isRealUser() && request.resource.data.uid == uid();
      allow read:   if isAdmin() || (isAuth() && resource.data.uid == uid());
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    match /boulangeries/{boulangerieId} {
      allow read:   if isAuth();
      allow create: if isAdmin();
      // Le propriétaire peut mettre à jour son profil, mais pas les champs financiers
      allow update: if isAdmin() ||
        (isOwner(boulangerieId)
          && unchanged('wallet')
          && unchanged('subscriptionStatus')
          && unchanged('subscriptionExpiresAt')
          && unchanged('vipStatus')
          && unchanged('vipExpiresAt')
          && unchanged('vipStartedAt')
          && unchanged('plan') && unchanged('priorityLevel')
          && unchanged('paymentStatus'));
      allow delete: if isAdmin();
      match /menu_items/{itemId} {
        allow read:  if isAuth();
        allow write: if isAdmin() || isOwner(boulangerieId);
      }
    }

    match /boulangerie_requests/{requestId} {
      allow create: if isRealUser() && request.resource.data.uid == uid();
      // Même exception propriétaire que driver_requests/seller_requests/
      // restaurant_requests (uid() prouvé par un vrai compte Firebase Auth,
      // pas une simple affirmation côté client) — sans elle, boulangerie_login.dart
      // ne pouvait jamais lire le statut de sa propre demande en attente
      // (permission-denied systématique), contrairement aux 3 rôles analogues.
      allow read:   if isAdmin() || (isAuth() && resource.data.uid == uid());
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    match /pharmacies/{pharmacieId} {
      // Le listing pharmacie (nom/adresse/horaires/garde) reste public aux
      // utilisateurs authentifiés (y compris anonymes) pour ne pas casser le
      // parcours client — ce n'est plus un risque puisque le mot de passe ne
      // vit plus ici : voir pharmacie_credentials ci-dessous, alimenté
      // uniquement par les Cloud Functions pharmacieLogin()/setPharmaciePassword().
      allow read:  if isAuth();
      // password/accessCode ne doivent plus jamais être écrits directement,
      // même par un admin — uniquement via setPharmaciePassword() (Admin SDK).
      allow write: if isAdmin()
        && !request.resource.data.keys().hasAny(['password', 'accessCode']);
      // currentUid est lié exclusivement par pharmacieLogin après validation
      // du mot de passe côté serveur (Admin SDK). Une session ne peut donc pas
      // s'attribuer elle-même une pharmacie depuis le client.
      // Le détenteur de cette liaison peut uniquement actualiser son token FCM.
      allow update: if isAuth()
        && resource.data.currentUid == uid()
        && request.resource.data.diff(resource.data).affectedKeys()
            .hasOnly(['fcmToken'])
        && request.resource.data.fcmToken is string
        && request.resource.data.fcmToken.size() > 10
        && request.resource.data.fcmToken.size() <= 4096;

      // Master Prompt "photos manquantes" : une fois la session déjà liée
      // (currentUid déjà écrit ci-dessus au login), la même session peut
      // modifier son logo et son statut de garde — jamais currentUid lui-même
      // dans cette branche (déjà couvert ci-dessus), jamais le wallet/password.
      // `isOnDuty` était déjà écrit directement par le client
      // (pharmacie_dashboard.dart:_toggle) sans qu'aucune règle ne l'autorise
      // jusqu'ici — corrigé au passage, même portée de risque que logoUrl.
      allow update: if isAuth()
        && resource.data.currentUid == uid()
        && request.resource.data.diff(resource.data).affectedKeys()
            .hasOnly(['logoUrl', 'isOnDuty']);
    }

    // Identifiants pharmacie hachés — écriture/lecture exclusivement via
    // pharmacieLogin()/setPharmaciePassword() (Cloud Functions, Admin SDK).
    match /pharmacie_credentials/{pharmacieId} {
      allow read, write: if false;
    }

    // LOT 6 SECURITY (2026-09) — PIN artisan haché, même schéma que
    // pharmacie_credentials ci-dessus. Remplace le stockage historique en
    // clair (service_providers/{id}.artisanPin), lisible jusqu'ici par tout
    // utilisateur authentifié via `allow read: if isAuth()` sur
    // service_providers (nécessaire pour l'annuaire public artisans — nom/
    // téléphone/photos — mais qui exposait aussi le PIN en clair dans le
    // même document). Écriture/lecture exclusivement via les Cloud Functions
    // setArtisanPin/artisanLogin (Admin SDK) — jamais directement par le
    // client. Migration paresseuse : les artisans déjà approuvés avant ce
    // correctif restent sur l'ancien champ en clair jusqu'à leur prochaine
    // réinitialisation de PIN ou une migration dédiée (planifiée, non
    // exécutée dans cette passe) — voir rapport LOT 6 SECURITY.
    match /artisan_credentials/{providerId} {
      allow read, write: if false;
    }

    // Tours de garde publics, distincts des comptes pharmacies partenaires.
    // Le client ne voit que les entrées actives et vérifiées. Les écritures
    // restent exclusivement administratives ; les synchronisations serveur
    // utilisent l'Admin SDK et ne dépendent pas de ces règles.
    match /pharmacy_guards/{guardId} {
      allow read: if isAdmin() || (isAuth()
        && resource.data.isActive == true
        && resource.data.isVerified == true);
      allow create, update: if isAdmin()
        && request.resource.data.name is string
        && request.resource.data.name.size() > 0
        && request.resource.data.city is string
        && request.resource.data.city.size() > 0
        && request.resource.data.guardStartAt is timestamp
        && request.resource.data.guardEndAt is timestamp
        && request.resource.data.guardEndAt > request.resource.data.guardStartAt
        && request.resource.data.sourceType in ['manual', 'external', 'partner']
        && request.resource.data.isVerified is bool
        && request.resource.data.isActive is bool;
      allow delete: if hasAdminPermission('demandes_vendeurs');
    }

    // Contrairement à driver_requests/seller_requests/restaurant_requests
    // (qui créent un vrai compte Firebase Auth email/mot de passe AVANT
    // d'écrire la demande, donc uid() == leur propre uid trivialement),
    // pharmacie_register.dart n'authentifie personne — la session est encore
    // anonyme par défaut côté mobile à ce stade (les pharmacies utilisent une
    // authentification Firestore custom, jamais Firebase Auth, voir
    // pharmacie_credentials). L'ancienne règle exigeait isRealUser() +
    // uid == caller alors que le code n'écrivait même pas de champ uid —
    // la création échouait donc à 100% des tentatives (permission-denied
    // systématique, corrigé 2026-07-09). Traité comme un formulaire de lead
    // pré-compte, même pattern que driver_applications/partner_applications :
    // écriture publique avec validation stricte de la forme des champs,
    // lecture réservée à l'admin (pas de lien à un compte propre possible).
    match /pharmacie_requests/{requestId} {
      allow create: if request.resource.data.keys().hasAll(['ownerName', 'pharmacieName', 'phone', 'address', 'status'])
        && request.resource.data.ownerName is string && request.resource.data.ownerName.size() > 0 && request.resource.data.ownerName.size() <= 200
        && request.resource.data.pharmacieName is string && request.resource.data.pharmacieName.size() > 0 && request.resource.data.pharmacieName.size() <= 200
        && request.resource.data.phone is string && request.resource.data.phone.size() > 0 && request.resource.data.phone.size() <= 30
        && request.resource.data.status == 'pending';
      allow read:   if isAdmin();
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    match /fleet_owners/{fleetId} {
      allow read:   if isOwner(fleetId) || isAdmin();
      allow create: if isRealUser() && uid() == fleetId;
      // Le propriétaire peut mettre à jour son profil, mais pas les champs financiers
      allow update: if isAdmin() ||
        (isOwner(fleetId)
          && unchanged('wallet')
          && unchanged('subscriptionStatus')
          && unchanged('subscriptionExpiresAt')
          && unchanged('vipStatus')
          && unchanged('vipExpiresAt')
          && unchanged('vipStartedAt') && unchanged('plan')
          && unchanged('priorityLevel') && unchanged('paymentStatus'));
      allow delete: if isAdmin();
    }

    match /orders/{orderId} {
      allow read: if isAuth() && (
        resource.data.clientId  == uid() ||
        resource.data.driverId  == uid() ||
        resource.data.sellerId  == uid() ||
        isPharmacieOwnerOfOrder()         ||
        isAdmin()
      );
      allow create: if isRealUser()
        && request.resource.data.clientId == uid()
        && request.resource.data.budget is int
        && request.resource.data.budget >= 500
        && notPresent('driverId')
        // isPaid ne peut être vrai à la création que pour un paiement wallet
        // (débit du client dans la même transaction Flutter que la création
        // de la commande — livraison_screen.dart/courses_screen.dart/
        // restaurant_menu.dart/boulangerie_order_page.dart) — jamais pour
        // cash. Bug confirmé en production le 2026-07-19 (audit modules) :
        // l'ancienne exigence isPaid==false inconditionnelle bloquait ces 4
        // écrans à 100% pour tout paiement wallet (permission-denied),
        // déjà suspecté sans preuve au Master Prompt 80. Ne réintroduit pas
        // la faille corrigée au Master Prompt 80 (crédit partenaire sans
        // paiement réel) : deliverOrderCF continue d'exiger indépendamment
        // order.isPaid==true avant tout crédit, quelle que soit la façon
        // dont isPaid est devenu true.
        && (request.resource.data.isPaid == false
            || (request.resource.data.isPaid == true
                && request.resource.data.get('paymentMethod', '') == 'wallet'
                && walletDebitMatchesPaidOrder(orderId)))
        && request.resource.data.status == 'pending';
      // LOT 6 SECURITY (2026-09) : la branche livreur ci-dessous ne protégeait
      // que budget/clientId/isPaid/paymentMethod/driverId — `shoppingBudget`
      // et `sellerId` (le bénéficiaire réel du crédit versé par
      // deliverOrderCF à la livraison) restaient librement réécrivables par
      // le livreur assigné pendant une transition de statut par ailleurs
      // légitime (ex. accepted→picked_up). Confirmé exploitable : un livreur
      // pouvait accepter une commande wallet déjà payée (isPaid déjà true,
      // fixé à la création) puis réécrire `sellerId`/`sellerType` vers un
      // compte partenaire de son choix avant de livrer — deliverOrderCF
      // créditerait alors intégralement ce nouveau bénéficiaire (isPaid déjà
      // vrai, la seule garde ajoutée au Master Prompt 80). `pharmacieId` est
      // protégé pour la même raison (route le crédit médicaments de
      // payOrderFromWalletCF). Aucun appelant légitime ne modifie ces champs
      // depuis le livreur (acceptOrder()/deliverOrderCF ne touchent jamais
      // shoppingBudget/sellerId/sellerType/pharmacieId) — élargissement de
      // sécurité pur.
      allow update: if isAdmin() ||
        (isAuth() && resource.data.driverId == uid()
          && unchanged('budget') && unchanged('clientId') && unchanged('isPaid')
          && unchanged('paymentMethod') && unchanged('driverId')
          && unchanged('shoppingBudget') && unchanged('sellerId')
          && unchanged('sellerType') && unchanged('pharmacieId')
          && (
            (resource.data.status == 'assigned'    && request.resource.data.status == 'accepted')
            || (resource.data.status == 'accepted' && request.resource.data.status == 'picked_up')
            // isPaid ne peut plus être flippé directement ici (faille confirmée
            // et corrigée, Master Prompt 80, 2026-07-09) : le passage à "payé"
            // (cash ou wallet) doit obligatoirement transiter par deliverOrderCF/
            // payOrderFromWalletCF (Admin SDK, validation serveur), jamais par
            // une écriture Firestore directe du livreur.
            || (resource.data.status == 'picked_up' && request.resource.data.status == 'delivered')
            || (resource.data.status == request.resource.data.status)
          )
        ) ||
        // Une boulangerie ne pilote que la préparation : elle ne peut jamais
        // réécrire le prix, les articles, le client, l'adresse ou les
        // coordonnées d'une commande déjà créée. Le tableau de bord ne fait
        // que ces deux transitions sellerStatus (voir
        // boulangerie_dashboard.dart:_updateSellerStatus).
        (isAuth() && resource.data.sellerId == uid()
          && resource.data.get('sellerType', '') == 'boulangerie'
          && request.resource.data.diff(resource.data).affectedKeys()
               .hasOnly(['sellerStatus'])
          && (
            ((resource.data.get('sellerStatus', null) == null
                || resource.data.get('sellerStatus', '') == '')
              && request.resource.data.sellerStatus == 'preparing')
            || (resource.data.get('sellerStatus', '') == 'preparing'
              && request.resource.data.sellerStatus == 'ready')
          )) ||
        // Les autres partenaires conservent leur flux existant ; le
        // resserrement ci-dessus est volontairement limité au module
        // Boulangerie audité.
        (isAuth() && resource.data.sellerId == uid()
          && resource.data.get('sellerType', '') != 'boulangerie'
          && unchanged('budget') && unchanged('clientId') && unchanged('isPaid')
          && unchanged('paymentMethod') && unchanged('driverId') && unchanged('status')) ||
        // Client annule sa commande en attente
        (isOwner(resource.data.clientId)
          && resource.data.status == 'pending'
          && request.resource.data.status == 'cancelled'
          && unchanged('budget') && unchanged('driverId') && unchanged('isPaid')) ||
        // Client peut noter le livreur ou le vendeur après livraison
        (isOwner(resource.data.clientId)
          && resource.data.status == 'delivered'
          && unchanged('status') && unchanged('budget') && unchanged('driverId')
          && unchanged('isPaid') && unchanged('paymentMethod')
          && request.resource.data.diff(resource.data).affectedKeys()
               .hasOnly(['rating', 'sellerRating']));
      // Phase 1: disable destructive purge, including from older Admin clients.
      allow delete: if false;
    }

    // ── Commissions AZ Express — lecture admin uniquement ────────────────────
    match /commissions/{commissionId} {
      allow read:  if isAdmin();
      allow write: if false;
    }

    match /wallet_transactions/{txId} {
      allow read: if isAuth() && (resource.data.userId == uid() || resource.data.uid == uid() || isAdmin());
      // Unique écriture cliente légitime : le journal E-Kbine
      // (lib/ekbine/services/ek_service.dart) — exactement ces 4 champs.
      // Tout le flux FeexPay (recharges) est écrit par Cloud Function via
      // l'Admin SDK, qui contourne ces règles : un client ne doit donc jamais
      // pouvoir fabriquer ici un document ressemblant à un paiement confirmé
      // (status/credited/userId/amount arbitraires), ce que l'ancienne règle
      // — sans aucune contrainte de champs — autorisait.
      allow create: if isAuth()
        && request.resource.data.keys().hasOnly(['uid', 'type', 'amount', 'createdAt'])
        && request.resource.data.uid == uid()
        && request.resource.data.type == 'ekbine_payment'
        && request.resource.data.amount is int;
      allow update: if false;
      allow delete: if isAdmin();
    }

    match /withdrawal_requests/{reqId} {
      allow read: if isAuth() && (resource.data.userId == uid() || isAdmin());
      // Création interdite au client : un retrait engage un mouvement d'argent
      // réel et n'est créé que par `initiateWithdrawal` (Admin SDK), qui débite
      // le wallet dans la même transaction et écrit `status:'processing'`.
      // L'ancienne règle autorisait une création cliente avec
      // `status == 'pending'` — un état que le serveur n'écrit jamais : elle
      // ne décrivait donc plus aucun flux réel, et le seul appelant Flutter
      // (`FirestoreService.createWithdrawalRequest`) est du code mort, sans
      // aucun appelant. Interdire la création ferme cette porte plutôt que de
      // se contenter d'aligner le nom du statut.
      allow create: if false;
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    match /recharge_requests/{reqId} {
      allow read: if isAuth() && (resource.data.userId == uid() || isAdmin());
      allow create: if isRealUser()
        && request.resource.data.userId == uid()
        && request.resource.data.status == 'pending'
        && request.resource.data.amount is int
        && request.resource.data.amount >= 100;
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    match /ekbine_orders/{orderId} {
      allow read: if isAuth() && (
        resource.data.clientId == uid() || resource.data.agentId == uid() || isAdmin()
      );
      allow create: if isRealUser()
        && request.resource.data.clientId == uid()
        && request.resource.data.status == 'pending'
        && notPresent('agentId')
        && request.resource.data.amount is int
        && request.resource.data.amount >= 100;
      allow update: if isAdmin() ||
        (isAuth() && (
          // Assignment is server-only: it snapshots the agent's number for
          // the requested operator and rejects suspended/unsubscribed agents.
          (resource.data.status == 'pending'
            && request.resource.data.status == 'server_assigned_only'
            && request.resource.data.agentId == uid()
            && unchanged('clientId') && unchanged('amount') && unchanged('fee')
            && unchanged('totalPaid') && unchanged('paymentMethod')) ||
          (resource.data.status == 'assigned' && resource.data.agentId == uid()
            && request.resource.data.status == 'in_progress'
            && unchanged('clientId') && unchanged('agentId')) ||
          // Deposit confirmation is Cloud Function only; an agent cannot
          // directly promote awaiting_deposit to in_progress.
          (resource.data.status == 'deposit_confirmed' && resource.data.agentId == uid()
            && request.resource.data.status == 'in_progress'
            && unchanged('clientId') && unchanged('agentId') && unchanged('amount')
            && unchanged('agentDepositNumber') && unchanged('agentDepositOperator')
            && unchanged('agentDepositAccountId')
            && get(/databases/$(database)/documents/ekbine_agents/$(uid())).data.isVerified == true
            && get(/databases/$(database)/documents/ekbine_agents/$(uid())).data.isSuspended != true
            && get(/databases/$(database)/documents/ekbine_agents/$(uid())).data.subscriptionStatus in ['trial', 'active']) ||
          (resource.data.status == 'in_progress' && resource.data.agentId == uid()
            && request.resource.data.status == 'proof_sent'
            && unchanged('clientId') && unchanged('agentId') && unchanged('amount')
            && unchanged('agentDepositNumber') && unchanged('agentDepositOperator')
            && unchanged('agentDepositAccountId'))
        )) ||
        (isAuth() && resource.data.clientId == uid() && (
          // completed : interdit en direct — passe obligatoirement par ekClientConfirmOrder (CF)
          // pour créditer le wallet agent atomiquement
          // agentDepositNumber/Operator/AccountId : figés dès l'acceptation
          // (snapshot immuable écrit par ekbineAcceptOrder) — le client ne
          // doit jamais pouvoir les modifier, y compris en profitant d'une
          // transition par ailleurs légitime (annulation, litige).
          ((resource.data.status == 'pending' || resource.data.status == 'awaiting_deposit')
            && request.resource.data.status == 'cancelled'
            && unchanged('agentId') && unchanged('amount')
            && unchanged('agentDepositNumber') && unchanged('agentDepositOperator')
            && unchanged('agentDepositAccountId')) ||
          // Deposit proof is written only by ekbineSubmitDepositProof.
          (resource.data.status == 'awaiting_deposit'
            && request.resource.data.status == 'server_deposit_proof_only'
            && unchanged('agentId') && unchanged('amount') && unchanged('agentEarning')) ||
          (resource.data.status == 'proof_sent'
            && request.resource.data.status == 'disputed'
            && unchanged('agentId') && unchanged('amount')
            && unchanged('agentDepositNumber') && unchanged('agentDepositOperator')
            && unchanged('agentDepositAccountId'))
        ));
      allow delete: if isAdmin();
    }

    match /ekbine_agents/{agentId} {
      allow read: if isAuth();
      allow create: if isRealUser() && uid() == agentId
        && request.resource.data.isVerified  == false
        && request.resource.data.isSuspended == false
        && request.resource.data.walletBalance  == 0
        && request.resource.data.totalCompleted == 0
        && !request.resource.data.keys().hasAny([
          'subscriptionStatus', 'subscriptionExpiresAt',
          'vipStatus', 'vipExpiresAt', 'vipStartedAt',
          'plan', 'priorityLevel', 'paymentStatus'
        ]);
      allow update: if isAdmin() ||
        (isOwner(agentId) && unchanged('walletBalance') && unchanged('isVerified')
          && unchanged('isSuspended') && unchanged('rating') && unchanged('ratingCount')
          && unchanged('totalCompleted')
          && unchanged('subscriptionStatus') && unchanged('subscriptionExpiresAt')
          && unchanged('vipStatus') && unchanged('vipExpiresAt')
          && unchanged('vipStartedAt') && unchanged('plan')
          && unchanged('priorityLevel') && unchanged('paymentStatus')) ||
        // Wallet crédité uniquement via Cloud Function ekClientConfirmOrder
        // Écriture directe depuis le client interdite pour éviter l'injection de montants arbitraires
        // Client note l'agent après service — lié à une commande completed de cet agent
        (isAuth()
          && request.resource.data.diff(resource.data).affectedKeys()
               .hasOnly(['rating', 'ratingCount'])
          && request.resource.data.ratingCount == resource.data.ratingCount + 1
          && 'lastOrderId' in resource.data
          && exists(/databases/$(database)/documents/ekbine_orders/$(resource.data.lastOrderId))
          && get(/databases/$(database)/documents/ekbine_orders/$(resource.data.lastOrderId)).data.clientId == uid()
          && get(/databases/$(database)/documents/ekbine_orders/$(resource.data.lastOrderId)).data.agentId == agentId
          && get(/databases/$(database)/documents/ekbine_orders/$(resource.data.lastOrderId)).data.status == 'completed');
      allow delete: if isAdmin();
    }

    match /ekbine_chats/{orderId} {
      function ekOrderParticipant() {
        let order = get(/databases/$(database)/documents/ekbine_orders/$(orderId)).data;
        return uid() == order.clientId || uid() == order.agentId;
      }
      allow read, write: if isAdmin() || (isAuth() && ekOrderParticipant());
      match /messages/{msgId} {
        allow read:   if isAdmin() || (isAuth() && ekOrderParticipant());
        allow create: if isAuth() && ekOrderParticipant()
          && request.resource.data.senderId == uid()
          && request.resource.data.keys().hasAll(['senderId','senderRole','type'])
          && request.resource.data.type in ['text','audio'];
        allow update, delete: if isAdmin();
      }
