      // Création exclusivement via publishMarketplaceProduct : les règles ne
      // peuvent pas compter atomiquement les annonces actives d'un vendeur.
      allow create: if isAdmin();
      allow update: if isAdmin()
        // Propriétaire modifie son annonce (sans toucher views/favoritesCount)
        || (isRealUser() && resource.data.sellerId == uid()
          && unchanged('sellerId') && unchanged('views') && unchanged('favoritesCount')
          && unchanged('expiresAt') && unchanged('sellerVerified')
          && unchanged('sellerVipStatus') && unchanged('priorityLevel')
          && (unchanged('status')
            || (resource.data.status == 'active'
              && request.resource.data.status in ['hidden', 'sold'])))
        // N'importe quel utilisateur peut incrémenter les vues uniquement
        || (isAuth()
          && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['views']))
        // N'importe quel utilisateur peut modifier favoritesCount uniquement
        || (isAuth()
          && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['favoritesCount']));
      allow delete: if isAdmin() || (isRealUser() && resource.data.sellerId == uid());
    }

    match /marketplace_favorites/{userId} {
      allow read, write: if isOwner(userId);
      match /items/{itemId} { allow read, write: if isOwner(userId); }
    }

    match /marketplace_chats/{chatId} {
      // Master Prompt "Corrections finales avant publication" — Bug Majeur #3 :
      // chatId = 'mp_<productId>_<buyerUid>' — l'ancien pattern [^_]+ supposait
      // un productId sans underscore, ce qui échouait dès qu'un ID de produit en
      // contenait un (ex: un ID personnalisé). `.*` (glouton) retrouve toujours
      // la bonne coupure juste avant le suffixe _<uid> exact, quel que soit le
      // contenu du segment productId — même niveau de sécurité (le suffixe uid
      // doit toujours correspondre exactement à l'appelant), juste indépendant
      // du format de l'ID.
      allow read, write: if isAdmin() || (isAuth() && (
        chatId.matches('mp_.*_' + uid())
        || (resource != null && resource.data.sellerId == uid())
        || (request.resource != null && request.resource.data.sellerId == uid())
      ));
      match /messages/{msgId} {
        allow read: if isAuth() && (isAdmin()
          || chatId.matches('mp_.*_' + uid())
          || get(/databases/$(database)/documents/marketplace_chats/$(chatId)).data.sellerId == uid());
        // Corrigé (Master Prompt "Corrections finales avant publication",
        // test réel "premier message") : le client (mp_chat_page.dart:_addMessage)
        // écrit le champ `senderUid`, jamais `senderId` — cette règle vérifiait
        // un nom de champ qui n'a jamais existé dans le document réel, donc
        // `request.resource.data.senderId` était toujours absent et l'accès par
