        // message, depuis toujours, indépendamment du bug de regex ci-dessus).
        // Même exigence de sécurité (l'expéditeur doit être l'appelant), juste
        // sur le bon nom de champ.
        allow create: if isAuth()
          && request.resource.data.senderUid == uid()
          && request.resource.data.keys().hasAll(['senderUid','type'])
          && request.resource.data.type in ['text','audio'];
        allow update, delete: if isAdmin();
      }
