    // anciens noms de champs hérités (lat/lng/latitude/longitude) — plus
    // aucun n'est autorisé en écriture directe, qu'ils soient exacts ou non.
    function locationFieldsUnchanged() {
      return unchanged('publicLatitude') && unchanged('publicLongitude')
        && unchanged('publicGeohash') && unchanged('hasExactLocation')
        && unchanged('locationUpdatedAt') && unchanged('locationPrivacy')
        && unchanged('lat') && unchanged('lng')
        && unchanged('latitude') && unchanged('longitude');
    }
    function noDirectLocationFieldsOnCreate() {
      return notPresent('publicLatitude') && notPresent('publicLongitude')
        && notPresent('publicGeohash') && notPresent('hasExactLocation')
        && notPresent('locationUpdatedAt') && notPresent('locationPrivacy')
        && notPresent('lat') && notPresent('lng')
