        || (isAuth() && resource.data.get('status', 'active') == 'active');
      allow create: if isRealUser()
        && request.resource.data.agentId == uid()
        && exists(/databases/$(database)/documents/real_estate_agents/$(uid()))
        && get(/databases/$(database)/documents/real_estate_agents/$(uid())).data.isVerified == true
        && get(/databases/$(database)/documents/real_estate_agents/$(uid())).data.isActive == true
        && request.resource.data.status in ['active', 'hidden']
        && request.resource.data.price is int && request.resource.data.price > 0
        && noDirectLocationFieldsOnCreate();
      allow update: if isAdmin()
        // Master Prompt "Immobilier V6.2" — Mission 11 : `createdAt` n'était
        // jusqu'ici protégé par aucune règle — seuls `agentId`/`views`
        // l'étaient — un `.update()` normal du propriétaire aurait donc pu
