        // ajout de cette mission (le reste de la règle était déjà correct :
        // agentId immuable, GPS jamais modifiable en écriture directe).
        || (isRealUser() && resource.data.agentId == uid()
          && exists(/databases/$(database)/documents/real_estate_agents/$(uid()))
          && get(/databases/$(database)/documents/real_estate_agents/$(uid())).data.isVerified == true
          && get(/databases/$(database)/documents/real_estate_agents/$(uid())).data.isActive == true
          && unchanged('agentId') && unchanged('views') && unchanged('createdAt')
          && locationFieldsUnchanged())
        || (isAuth()
          && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['views'])
