    match /real_estate_private_locations/{listingId} {
      allow read: if isAdmin()
        || (isRealUser() && resource.data.agentId == uid())
        || (isAuth()
          && exists(/databases/$(database)/documents/real_estate_location_access/$(listingId + '_' + uid()))
          && get(/databases/$(database)/documents/real_estate_location_access/$(listingId + '_' + uid())).data.isActive == true);
      allow write: if false;
