    match /real_estate_location_access/{accessId} {
      allow read: if isAdmin() || (isAuth() && resource.data.clientId == uid());
      allow write: if false;
    }

    match /sos_alerts/{alertId} {
      allow read:   if isAdmin();
      // Le livreur envoie driverId (pas clientId)
      allow create: if isAuth()
        && request.resource.data.status == 'active'
        && (request.resource.data.keys().hasAll(['clientId','lat','lng','timestamp','status'])
