    match /boutique_products/{productId} {
      allow read: if isAuth();
      allow create: if isAdmin()
        || (isRealUser() && request.resource.data.sellerId == uid());
      allow update: if isAdmin()
        || (isRealUser()
          && resource.data.sellerId == uid()
          && unchanged('sellerId'));
      allow delete: if isAdmin()
        || (isRealUser() && resource.data.sellerId == uid());
