      // isRealUser() casserait le login. Mitigation : Phase 5 — migrer vers Cloud Function artisanLogin().
      allow read:  if isAuth();
      // LOT 6.2 SECURITY (2026-09) : `artisanPin` ne doit plus jamais pouvoir
      // être (ré)écrit en clair sur ce document, y compris par un admin —
      // seul setArtisanPin (Cloud Function, Admin SDK, hache dans
      // artisan_credentials) doit désormais renseigner un PIN. Sans ce
      // verrou, un build ADMIN plus ancien que ce correctif (qui écrivait
      // encore directement `service_providers.artisanPin` en clair) aurait
      // pu réintroduire silencieusement la faille corrigée au LOT 6 à chaque
      // nouvelle approbation/édition — un vrai risque de régression par
      // désynchronisation de version, pas seulement côté client.
      //
      // LOT 6.3 SECURITY — bug réel trouvé et corrigé dans CE verrou lui-même :
      // la première version (`!('artisanPin' in request.resource.data)`)
      // vérifiait l'ABSENCE du champ dans le document RÉSULTANT — pour un
      // `update()`, ce document résultant inclut tous les champs existants
      // non touchés (fusion, pas remplacement). Conséquence non anticipée :
      // sur un ancien artisan pas encore migré (artisanPin encore présent
      // en clair), TOUTE mise à jour admin — même approuver le dossier,
      // même changer isAvailable, sans jamais toucher artisanPin — était
      // rejetée en bloc, puisque le champ hérité restait "présent". Confirmé
      // par test réel contre l'émulateur avant correction (pas supposé).
      // Corrigé : `notPresent('artisanPin') || unchanged('artisanPin')` —
      // autorise (a) les documents qui n'ont jamais eu ce champ, (b) une
      // mise à jour qui n'introduit ni ne modifie sa valeur (le cas bloqué
      // à tort ci-dessus, y compris quand la valeur héritée est identique
      // des deux côtés), et (c) sa suppression (FieldValue.delete(), le
      // champ devient absent -> notPresent devient vrai) ; rejette
      // uniquement l'introduction d'une valeur NOUVELLE ou MODIFIÉE — le
      // seul cas qui reproduirait la fuite déjà corrigée. setArtisanPin et
      // le script de migration restent de toute façon en Admin SDK, hors
      // d'atteinte de cette règle dans les deux versions.
      allow create, update: if isAdmin()
        && (notPresent('artisanPin') || unchanged('artisanPin'));
      allow delete: if isAdmin();
      allow update: if isRealUser() && !('artisanUid' in resource.data)
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['artisanUid'])
        && request.resource.data.artisanUid == uid();
      allow update: if isRealUser() && 'artisanUid' in resource.data
        && resource.data.artisanUid == uid()
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['photos']);
    }

