        && request.resource.data.status == 'pending'
        && request.resource.data.get('isSuspended', false) == false
        && request.resource.data.requestedPlan in ['standard', 'premium', 'vvip']
        && request.resource.data.get('planStatus', 'pending') == 'pending'
        && !('plan' in request.resource.data)
        && !('priorityLevel' in request.resource.data)
        && !('planStartedAt' in request.resource.data)
        && !('trialStartedAt' in request.resource.data)
        && !('trialEndsAt' in request.resource.data)
        && !('planEndsAt' in request.resource.data)
