          && unchanged('rating') && unchanged('reviewCount')
          && unchanged('plan') && unchanged('priorityLevel')
          && unchanged('planStatus') && unchanged('planStartedAt')
          && unchanged('trialStartedAt') && unchanged('trialEndsAt')
