    match /event_offers/{offerId} {
      allow read: if isAdmin()
        || (isAuth() && resource.data.ownerId == uid())
        || (isAuth() && resource.data.get('isActive', false) == true);
      allow create: if isRealUser()
        && request.resource.data.ownerId == uid()
        && existsAfter(/databases/$(database)/documents/event_providers/$(request.resource.data.providerId))
        && getAfter(/databases/$(database)/documents/event_providers/$(request.resource.data.providerId)).data.ownerId == uid()
        && (
          (getAfter(/databases/$(database)/documents/event_providers/$(request.resource.data.providerId)).data.status == 'approved'
            && getAfter(/databases/$(database)/documents/event_providers/$(request.resource.data.providerId)).data.get('isSuspended', false) == false)
