    // Marqueur écrit uniquement par la Function de modération. Il évite une
    // lecture/validation coûteuse du profil sur chaque écriture d'annonce.
    match /vehicle_seller_suspensions/{sellerId} {
      allow read, write: if false;
    }

    // Signalements Auto & Moto : identifiant déterministe pour dédupliquer
    // cible + auteur. Seul l'admin peut les lire et les modérer.
    match /vehicle_reports/{reportId} {
      function validVehicleReport(data) {
        let listingPath = /databases/$(database)/documents/vehicle_listings/$(data.targetId);
        let sellerPath = /databases/$(database)/documents/vehicle_seller_profiles/$(data.targetId);
        return data.keys().hasAll([
            'targetType', 'targetId', 'sellerId', 'reporterUid', 'reason',
            'status', 'createdAt'
          ])
          && data.keys().hasOnly([
            'targetType', 'targetId', 'sellerId', 'reporterUid', 'reason',
            'details', 'status', 'createdAt'
          ])
          && data.targetType in ['listing', 'seller']
          && data.targetId is string && data.targetId.size() > 0
          && data.sellerId is string && data.sellerId.size() > 0
          && data.reporterUid == uid()
          && data.reporterUid != data.sellerId
          && data.reason is string
          && data.reason.size() > 0 && data.reason.size() <= 80
          && (!('details' in data)
            || (data.details is string
              && data.details.size() > 0 && data.details.size() <= 300))
          && data.status == 'pending'
          && data.createdAt == request.time
          && reportId == data.targetType + '_' + data.targetId + '_' + uid()
          && ((data.targetType == 'listing'
              && exists(listingPath)
              && get(listingPath).data.sellerId == data.sellerId)
            || (data.targetType == 'seller'
              && data.targetId == data.sellerId
              && exists(sellerPath)
              && get(sellerPath).data.ownerId == data.sellerId));
      }

      allow create: if isRealUser() && validVehicleReport(request.resource.data);
      allow read: if isAdmin();
      allow update, delete: if isAdmin();
    }

    // Blocages privés : aucun document parent lisible, un document par UID.
    match /vehicle_user_blocks/{ownerUid} {
      allow read, write: if false;
      match /blocked/{blockedUid} {
        allow read: if isRealUser() && ownerUid == uid();
        allow create: if isRealUser()
          && ownerUid == uid()
          && blockedUid != uid()
          && request.resource.data.keys()
            .hasOnly(['ownerUid', 'blockedUid', 'createdAt'])
          && request.resource.data.ownerUid == uid()
          && request.resource.data.blockedUid == blockedUid
          && request.resource.data.createdAt == request.time;
        allow update: if false;
        allow delete: if isRealUser() && ownerUid == uid();
      }
    }

    // Favoris Auto & Moto privés et scalables : un document par annonce,
    // sous le seul UID propriétaire. Le snapshot évite les lectures N+1.
    match /vehicle_favorites/{userId} {
      allow read, write: if false;

      match /items/{listingId} {
        allow read: if isRealUser() && userId == uid();
        allow create: if isRealUser()
          && userId == uid()
          && listingId == request.resource.data.listingId
          && request.resource.data.userId == uid()
          && request.resource.data.keys().hasOnly([
            'userId', 'listingId', 'listingSnapshot', 'createdAt'
          ])
          && request.resource.data.listingSnapshot is map
          && request.resource.data.createdAt == request.time
          && exists(/databases/$(database)/documents/vehicle_listings/$(listingId))
          && get(/databases/$(database)/documents/vehicle_listings/$(listingId)).data.status
            == 'active';
        allow update: if false;
        allow delete: if isRealUser() && userId == uid();
      }
    }

    match /event_chats/{chatId} {
      allow read: if isAdmin()
        || (isAuth() && uid() in resource.data.participantIds);
        allow create: if isAuth()
          && uid() in request.resource.data.participantIds
          && request.resource.data.participantIds.size() == 2
          && request.resource.data.clientId == uid()
          && exists(/databases/$(database)/documents/event_providers/$(request.resource.data.providerId))
          && get(/databases/$(database)/documents/event_providers/$(request.resource.data.providerId)).data.ownerId
              in request.resource.data.participantIds;
      allow update: if isAuth() && uid() in resource.data.participantIds
        && request.resource.data.diff(resource.data).affectedKeys()
            .hasOnly(['lastMessage', 'lastSenderId', 'updatedAt'])
          && (
            request.resource.data.diff(resource.data).affectedKeys()
                .hasOnly(['updatedAt'])
            || (
              request.resource.data.lastSenderId == uid()
              && request.resource.data.lastMessage is string
              && request.resource.data.lastMessage.size() <= 2000
            )
          );
      allow delete: if isAdmin();
      match /messages/{messageId} {
        allow read: if isAdmin()
          || (isAuth()
            && uid() in get(/databases/$(database)/documents/event_chats/$(chatId)).data.participantIds);
        allow create: if isAuth()
          && request.resource.data.senderId == uid()
          && request.resource.data.keys()
              .hasOnly(['senderId', 'text', 'createdAt'])
          && request.resource.data.text is string
          && request.resource.data.text.size() > 0
          && request.resource.data.text.size() <= 2000
          && uid() in get(/databases/$(database)/documents/event_chats/$(chatId)).data.participantIds;
        allow update, delete: if false;
      }
    }
  }
}
